# ---------------------------------------------------------------------------
# writer
# ---------------------------------------------------------------------------
def load_dir(sub):
    d = os.path.join(KNOW, sub)
    out = {}
    for fn in os.listdir(d):
        if not fn.endswith(".json"):
            continue
        with open(os.path.join(d, fn), encoding="utf-8") as f:
            out[os.path.splitext(fn)[0]] = json.load(f)
    return out


def main():
    links = load_dir("links")
    hazards = load_dir("hazards")
    clauses = load_dir("clauses")
    reviews = load_dir(os.path.join("reviews", "links"))
    missing = [k for k in links if k not in D and not (reviews.get(k) or {}).get("reviewer")]
    if missing:
        print(f"ERROR: {len(missing)} pending links have no decision: {missing}")
        return 1

    written, skipped = [], []
    for kid, (decision, codes, reason) in D.items():
        link = links[kid]
        revpath = os.path.join(REVDIR, kid + ".json")
        if os.path.exists(revpath):
            with open(revpath, encoding="utf-8") as f:
                old = json.load(f)
            if old.get("reviewer"):
                print(f"SKIP already reviewed: {kid} ({old.get('reviewer')})")
                skipped.append(kid)
                continue
        else:
            old = {}
        new = {
            "entityType": "link",
            "entityId": kid,
            "reviewType": REVIEW_TYPE,
            "decision": decision,
            "reviewedContentHash": content_hash(link),
            "contextHashes": {
                "hazard": content_hash(hazards[link["hazardId"]]),
                "clause": content_hash(clauses[link["clauseId"]]),
            },
            "checkedAt": CHECKED_AT,
            "reviewer": REVIEWER,
            "reason": reason,
            "reasonCodes": codes,
            "evidenceRefs": old.get("evidenceRefs", []),
            "migratedFromV3Verification": old.get("migratedFromV3Verification"),
        }
        with open(revpath, "w", encoding="utf-8") as f:
            json.dump(new, f, ensure_ascii=False, indent=2)
        written.append((kid, decision))

    from collections import Counter
    cnt = Counter(d for _, d in written)
    print(f"written: {len(written)}  decisions={dict(cnt)}")
    print(f"skipped (already reviewed): {len(skipped)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
